async function handleFactoryTick(env,u,server){
 const usernames=u?[u.username]:((await env.DB.prepare('SELECT username FROM users WHERE server=?').bind(server).all()).results||[]).map(x=>x.username);
 const allOut=[],t=now();
 for(const username of usernames){
  const actor=u||{username,server};
  const legacy=(await env.DB.prepare('SELECT factory_key FROM factory_lines WHERE username=? AND server=?').bind(username,server).all()).results||[];
  for(const x of legacy)await migrateLegacyFactoryLine(env,username,server,String(x.factory_key));
  const factories=(await env.DB.prepare('SELECT DISTINCT factory_key FROM factory_model_lines WHERE username=? AND server=? AND queued>0').bind(username,server).all()).results||[];
  for(const frow of factories){
   const fk=String(frow.factory_key);
   const factorySite=await resolveFactorySite(env,username,server,fk);
   if(!factorySite||Number(factorySite.integrity||0)<=0||!['factory','shipyard'].includes(String(factorySite.site_type)))continue;
   const queue=(await env.DB.prepare(`SELECT * FROM factory_model_lines WHERE username=? AND server=? AND factory_key=? AND queued>0 ORDER BY COALESCE(NULLIF(queue_order_at,0),last_tick),created_at,model`).bind(username,server,fk).all()).results||[];
   if(!queue.length)continue;
   let cursor=Math.max(0,safeInt(queue[0].last_tick,t));
   let save=null,saveChanged=false;
   for(let qi=0;qi<queue.length;qi++){
    const line=queue[qi],model=String(line.model||''),meta=MODEL_META[model];
    if(!meta||!factoryModelAllowed(factorySite.site_key||fk,model,factorySite.site_type,factorySite.game_type))break;
    const interval=factoryUnitIntervalMs(model,factorySite),queued=Math.max(0,safeInt(line.queued));
    if(!queued)continue;
    // The first unit of this model starts when the previous model's entire batch ends.
    // Persist that absolute start time so leaving/re-entering never restarts the clock.
    const startAt=cursor;
    if(safeInt(line.last_tick)!==startAt){
     await env.DB.prepare('UPDATE factory_model_lines SET last_tick=?,updated_at=? WHERE username=? AND server=? AND factory_key=? AND model=? AND queued>0').bind(startAt,t,username,server,fk,model).run();
    }
    const elapsed=Math.max(0,t-startAt);
    let can=Math.min(queued,Math.floor(elapsed/interval));
    if(can<=0)break;
    const paidAvailable=Math.min(can,Math.max(0,safeInt(line.prepaid_queue)));
    let resourceCan=can-paidAvailable;
    if(resourceCan>0){
     if(!save){save=await getSave(env,username,server)||{server,units:{},oil:0,steel:0,food:0};save.units=save.units||{};}
     for(const [res,cost] of Object.entries(meta.materials||{}))resourceCan=Math.min(resourceCan,Math.floor(Math.max(0,safeInt(save[res]))/Math.max(1,safeInt(cost,1))));
     can=paidAvailable+resourceCan;
    }
    if(can<=0){
     // No resources for a legacy unpaid queue: pause its clock instead of allowing
     // an unpaid backlog to complete instantly after the player returns.
     await env.DB.prepare('UPDATE factory_model_lines SET last_tick=?,updated_at=? WHERE username=? AND server=? AND factory_key=? AND model=?').bind(t,t,username,server,fk,model).run();
     break;
    }
    const paid=Math.min(can,Math.max(0,safeInt(line.prepaid_queue))),normal=can-paid;
    if(normal>0){
     if(!save){save=await getSave(env,username,server)||{server,units:{},oil:0,steel:0,food:0};save.units=save.units||{};}
     for(const [res,cost] of Object.entries(meta.materials||{}))save[res]=Math.max(0,safeInt(save[res])-safeInt(cost)*normal);
     saveChanged=true;
    }
    const remain=queued-can;
    const nextUnitStart=startAt+can*interval;
    const done=await env.DB.prepare(`UPDATE factory_model_lines SET queued=MAX(queued-?,0),produced=produced+?,prepaid_queue=MAX(prepaid_queue-?,0),prepaid=CASE WHEN MAX(prepaid_queue-?,0)>0 THEN 1 ELSE 0 END,last_tick=?,updated_at=? WHERE username=? AND server=? AND factory_key=? AND model=? AND queued>=?`).bind(can,can,paid,paid,remain>0?nextUnitStart:startAt+queued*interval,t,username,server,fk,model,can).run();
    if(!done.meta||safeInt(done.meta.changes)!==1)break;
    allOut.push({username,factoryKey:fk,model,produced:can,queued:remain,prepaid:paid,resourcePaid:normal,completedAt:nextUnitStart});
    // Carry forward the exact elapsed wall-clock timeline to the next model.
    cursor=startAt+queued*interval;
    if(remain>0)break;
    // If the next batch was already waiting while the player was offline,
    // continue processing it using the leftover elapsed time.
   }
   if(saveChanged&&save)await saveGame(env,actor,save);
  }
 }
 return allOut;
}
