for(let i=0;i<Math.min(elapsed,60);i++){price+=(target-price)*0.20;}price=Number(price.toFixed(2));await env.DB.prepare('UPDATE oil_market_state SET price=?,target_price=?,last_tick=?,updated_at=? WHERE server=?').bind(price,target,t,t,server).run();
